<?php
function citizen_next_update($issue) {
 switch ($issue['status']) {
  case 'Submitted': return 'The Province Admin will check your report and location.';
  case 'Verified': return 'Verified. Waiting for the Province Admin to assign a District Officer.';
  case 'Assigned': return empty($issue['maintenance_id'])
   ? 'Assigned to the District Officer. Waiting for a maintenance team.'
   : 'Assigned to a maintenance team. Waiting for the team to start.';
  case 'In Progress':
   $messages=[
    'Assigned'=>'Waiting for the new maintenance team to start.',
    'Blocked'=>'Work is on hold. The team or District Officer will follow up.',
    'Review'=>'Completion submitted. The District Officer is reviewing the evidence.',
    'Returned'=>'The District Officer requested more work.',
    'Officer Return'=>'The Province Admin returned the completion to the District Officer.'
   ];
   return $messages[$issue['maintenance_stage']] ?? 'The maintenance team is working on this issue.';
  case 'Awaiting Approval': return 'The District Officer accepted the completion. Waiting for Province Admin final approval.';
  case 'Resolved': return 'The Province Admin approved the completed work.';
 }
 return '';
}

function citizen_progress($i){
 if($i['status']==='Rejected'){
  $reason=photo_evidence_visible($i)?q("SELECT message FROM issue_events WHERE issue_id=? AND kind IN ('review','status') AND message LIKE '% → Rejected.%' ORDER BY id DESC LIMIT 1",[$i['id']])->fetchColumn():null;
  $reason=preg_replace('/^.*? → Rejected\.\s*/u','',(string)$reason);
  $reason=preg_replace('/^Priority: .*?\. Officer: .*?\. Area: .*?\. Due: .*?\.\s*/u','',$reason);
  ?><p class="small"><strong>Rejected.</strong> <?=e($reason?:(photo_evidence_visible($i)?'No rejection reason was recorded.':'This report was closed during review.'))?></p><?php
  return;
 }
 if($i['status']==='Duplicate'){
  ?><p class="small"><strong>Duplicate.</strong> <?php if($i['duplicate_of']):?><a class="text-link" href="index.php?page=issue&amp;id=<?=(int)$i['duplicate_of']?>">Follow original report #<?=(int)$i['duplicate_of']?> →</a><?php endif;?></p><?php
  return;
 }
 $stages=['Submitted','Verified','Assigned','In progress','Approval','Resolved'];
 $position=['Submitted'=>0,'Verified'=>1,'Assigned'=>2,'In Progress'=>3,'Awaiting Approval'=>4,'Resolved'=>5];
 $current=$position[$i['status']]??-1;
 ?><ol class="citizen-progress" aria-label="Report progress"><?php foreach($stages as $n=>$label):?><li class="<?=$current>=$n?'reached':''?>" <?=$current===$n?'aria-current="step"':''?>><span><?=$n+1?></span><small><?=e($label)?></small></li><?php endforeach;?></ol>
 <p class="small muted"><?=e(citizen_next_update($i))?></p><?php
}
function citizen_report_actions($i,$mine=false){
 $url='index.php?page=issue&id='.(int)$i['id'];?><div class="citizen-card-actions"><a class="button secondary" href="<?=e($url)?>"><?=$mine?($i['status']==='Rejected'?'View rejection reason':'View progress'):'View report'?> →</a><?php if($mine):if(editable_report($i)):?><a class="text-link" href="index.php?page=edit&amp;id=<?=$i['id']?>">Edit</a><a class="text-link" href="<?=e($url)?>#report-actions">Delete</a><?php elseif($i['status']==='Resolved'):?><a class="text-link" href="<?=e($url)?>#resolution-feedback">Feedback</a><a class="text-link" href="<?=e($url)?>#reopen-report">Reopen</a><?php endif;endif;?></div><?php
}
function citizen_card($i,$mine=false){?><article class="citizen-card"><a href="index.php?page=issue&amp;id=<?=$i['id']?>" class="citizen-card-photo"><?php report_photo($i,'',true); ?><span><?=e($i['category'])?></span></a><div class="citizen-card-body"><div class="row between"><?=badge($i['status'])?><small class="muted">#<?=str_pad($i['id'],4,'0',STR_PAD_LEFT)?></small></div><h3><a href="index.php?page=issue&amp;id=<?=$i['id']?>"><?=e($i['title'])?></a></h3><p class="small muted"><?=e($i['address'])?> · <?=e($i['area_name']?:'Area not specified')?></p><?php if($mine)citizen_progress($i);?><div class="citizen-card-meta"><span>Updated <?=e(date('d M Y',strtotime($i['updated_at'])))?></span><span><?=$i['support_count']?> supporting</span></div><?php citizen_report_actions($i,$mine);?></div></article><?php }
function citizen_counts(){return q("SELECT COUNT(*) total,COALESCE(SUM(status IN ('Submitted','Verified','Assigned')),0) pending,COALESCE(SUM(status IN ('In Progress','Awaiting Approval')),0) progress,COALESCE(SUM(status='Resolved'),0) resolved,COALESCE(SUM(status IN ('Rejected','Duplicate')),0) closed FROM issues WHERE user_id=?",[user()['id']])->fetch();}
function citizen_overview(){
 require_role('citizen');$stats=citizen_counts();$recent=q(issue_query().' WHERE i.user_id=? ORDER BY i.updated_at DESC,i.id DESC LIMIT 4',[user()['id']])->fetchAll();$categories=q('SELECT c.name,COUNT(*) total FROM issues i JOIN categories c ON c.id=i.category_id WHERE i.user_id=? GROUP BY c.id,c.name ORDER BY total DESC,c.name',[user()['id']])->fetchAll();
 layout_start('A better community starts here.','Welcome back, '.user()['name'].'. Follow your reports and recent updates.');
?><div class="citizen-workspace"><section class="citizen-welcome"><div><h2>Your neighbourhood. Your voice.</h2><p>Report an issue with a clear photo and an accurate location. Follow the response in My reports.</p></div><a class="text-link" href="index.php?page=mine">Open My reports →</a></section><section class="stats-grid" aria-label="My report counts"><?php foreach([['My reports',$stats['total'],'all'],['Pending review / work',$stats['pending'],'pending'],['In progress',$stats['progress'],'progress'],['Resolved',$stats['resolved'],'resolved']] as $c):?><a class="stat" href="index.php?page=mine&amp;tab=<?=$c[2]?>"><span><?=e($c[0])?></span><strong><?=$c[1]?></strong><small>View my reports ↗</small></a><?php endforeach;?></section><p class="small muted citizen-count-note">Pending, In progress and Resolved are separate groups. Rejected/duplicate reports are under Closed (<?=$stats['closed']?>).</p><div class="citizen-section-heading"><h2>Recent reports</h2><a class="text-link" href="index.php?page=mine">View all ↗</a></div><?php if(!$recent):?><section class="panel citizen-empty"><h3>Your first report starts here</h3><p>Reports you submit and their latest progress appear here.</p><a class="button" href="index.php?page=report">Report an issue →</a></section><?php else:?><div class="citizen-grid"><?php foreach($recent as $i)citizen_card($i,true);?></div><?php endif;?>
<section class="panel section-space"><details><summary>My report categories</summary><?php if(!$categories):?><p class="small muted">No categories to summarise yet.</p><?php endif;foreach($categories as $c):?><div class="row between summary-line"><span><?=e($c['name'])?></span><strong><?=$c['total']?></strong></div><?php endforeach;?></details><p class="small muted" style="margin:16px 0 0">Updates and dates shown here relate to your own reports. A report without a due date uses a 7-day attention indicator, which is not an official service deadline.</p></section></div><?php layout_end();
}
function citizen_listing($page){
 require_role('citizen');$mine=$page==='mine';$map=$page==='map';$groups=['all'=>[],'pending'=>['Submitted','Verified','Assigned'],'progress'=>['In Progress','Awaiting Approval'],'resolved'=>['Resolved'],'closed'=>['Rejected','Duplicate']];$tab=(string)($_GET['tab']??'all');if(!isset($groups[$tab]))$tab='all';$display=($_GET['display']??'cards')==='list'?'list':'cards';$scope=($_GET['scope']??'all')==='mine'?'mine':'all';
 $search=trim(substr((string)($_GET['search']??''),0,160));$status=(string)($_GET['status']??'');$cat=max(0,(int)($_GET['category']??0));$area=max(0,(int)($_GET['area']??0));$sort=(string)($_GET['sort']??'newest');$sorts=['newest'=>'i.created_at DESC,i.id DESC','updated'=>'i.updated_at DESC,i.id DESC','supported'=>'support_count DESC,i.id DESC'];if(!isset($sorts[$sort]))$sort='newest';
 $w=['1=1'];$p=[];if($mine||($map&&$scope==='mine')){$w[]='i.user_id=?';$p[]=user()['id'];}if($mine&&$groups[$tab]){$w[]='i.status IN ('.implode(',',array_fill(0,count($groups[$tab]),'?')).')';$p=array_merge($p,$groups[$tab]);}
 if($search!==''){$w[]='(i.title LIKE ? OR i.address LIKE ? OR i.id=?)';$p[]='%'.$search.'%';$p[]='%'.$search.'%';$p[]=(int)ltrim($search,'#');}if(in_array($status,staff_statuses(),true)){$w[]='i.status=?';$p[]=$status;}if($cat){$w[]='i.category_id=?';$p[]=$cat;}if($area){$w[]='i.area_id=?';$p[]=$area;}
 $sql=' WHERE '.implode(' AND ',$w);$total=(int)q('SELECT COUNT(*) FROM issues i'.$sql,$p)->fetchColumn();$limit=$map?500:12;$max=max(1,(int)ceil($total/$limit));$pn=min($max,max(1,(int)($_GET['p']??1)));$rows=q(issue_query().$sql.' ORDER BY '.$sorts[$sort].' LIMIT '.$limit.' OFFSET '.(($pn-1)*$limit),$p)->fetchAll();
 layout_start($mine?'My reports':($map?'Community map':'Community reports'),$mine?'Your reports, latest updates and resolution feedback.':($map?'Explore issue locations or switch to your own reports.':'Explore community reports and support issues that affect you.'),$map);
?><div class="citizen-workspace"><?php if($mine):$stats=citizen_counts();$counts=['all'=>$stats['total'],'pending'=>$stats['pending'],'progress'=>$stats['progress'],'resolved'=>$stats['resolved'],'closed'=>$stats['closed']];?><nav class="citizen-tabs" aria-label="My report status"><?php foreach(['all'=>'All','pending'=>'Pending','progress'=>'In progress','resolved'=>'Resolved','closed'=>'Closed'] as $key=>$label):$query=$_GET;$query['page']='mine';$query['tab']=$key;unset($query['status'],$query['p']);?><a class="<?=$tab===$key?'selected':''?>" href="?<?=e(http_build_query($query))?>" <?=$tab===$key?'aria-current="page"':''?>><?=$label?> <b><?=$counts[$key]?></b></a><?php endforeach;?></nav><?php endif;?>
<form class="panel citizen-filters" method="get"><input type="hidden" name="page" value="<?=e($page)?>"><input type="hidden" name="display" value="<?=e($display)?>"><?php if($mine):?><input type="hidden" name="tab" value="<?=e($tab)?>"><?php endif;?><label class="citizen-search">Search reports<input type="search" name="search" maxlength="160" value="<?=e($search)?>" placeholder="Title, location or #ID"></label><?php if($map):?><label>Show<select name="scope"><option value="all" <?=$scope==='all'?'selected':''?>>All reports</option><option value="mine" <?=$scope==='mine'?'selected':''?>>My reports</option></select></label><?php endif;?><label>Category<select name="category"><option value="">All categories</option><?php foreach(categories() as $c):?><option value="<?=$c['id']?>" <?=$cat===(int)$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select></label><label>Area<select name="area"><option value="">All areas</option><?php foreach(service_areas() as $a):?><option value="<?=$a['id']?>" <?=$area===(int)$a['id']?'selected':''?>><?=e($a['name'])?></option><?php endforeach;?></select></label><label>Status<select name="status"><option value="">All statuses</option><?php foreach(staff_statuses() as $v):?><option <?=$status===$v?'selected':''?>><?=$v?></option><?php endforeach;?></select></label><?php if(!$map):?><label>Sort<select name="sort"><?php foreach(['newest'=>'Newest first','updated'=>'Recently updated','supported'=>'Most supported'] as $v=>$label):?><option value="<?=$v?>" <?=$sort===$v?'selected':''?>><?=$label?></option><?php endforeach;?></select></label><?php endif;?><div class="row"><button class="button secondary">Filter</button><a class="text-link" href="index.php?page=<?=e($page)?>">Reset</a></div></form>
<?php workspace_filter_chips(['search'=>$search,'category'=>$cat,'area'=>$area,'status'=>$status,'scope'=>$map?$scope:'all']);workspace_status_help();if($map):?><div class="row between citizen-map-tools"><details><summary>Find a place or street</summary><?php location_search('community-map');?></details><button type="button" id="community-locate" class="button secondary">Use my location</button></div><p id="community-location-status" class="small muted" role="status"></p><div class="officer-map-legend" aria-label="Map status colours"><?php foreach(officer_map_colours() as $label=>$color):?><span><i style="background:<?=$color?>"></i><?=e($label)?></span><?php endforeach;?></div><div id="community-map" class="officer-map" aria-label="Community reports map"></div><script type="application/json" id="map-data"><?=json_encode(array_map(function($i){return ['id'=>$i['id'],'title'=>$i['title'],'status'=>$i['status'],'latitude'=>$i['latitude'],'longitude'=>$i['longitude'],'color'=>officer_map_colours()[$i['status']]??'#697887'];},$rows),JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?></script><p class="small muted"><?=count($rows)?> of <?=$total?> reports on this map page. Use filters or pages to narrow larger selections.</p><details class="panel"><summary>Report list (<?=count($rows)?>)</summary><?php if($rows)issue_table($rows);else echo '<p>No reports match these filters.</p>';?></details>
<?php else:?><div class="citizen-section-heading"><h2><?=$total?> matching reports</h2><nav class="workspace-display" aria-label="Report display"><?php foreach(['cards'=>'Cards','list'=>'List'] as $view=>$label):$query=$_GET;$query['display']=$view;unset($query['p']);?><a class="<?=$display===$view?'selected':''?>" href="?<?=e(http_build_query($query))?>" <?=$display===$view?'aria-current="true"':''?>><?=$label?></a><?php endforeach;?></nav></div><?php if(!$rows):?><section class="panel citizen-empty"><h3>No reports found.</h3><p>Try another filter or create a report about an issue you have seen.</p></section><?php elseif($display==='list'):workspace_report_list($rows);else:?><div class="citizen-grid"><?php foreach($rows as $i)citizen_card($i,$mine);?></div><?php endif;endif;admin_pager($pn,$max,$total);?></div><?php layout_end();
}

function citizen_notification_type($message){foreach(['comment'=>'New comment','feedback'=>'Feedback','reopened'=>'Report reopened','resolved'=>'Resolution update','approval'=>'Approval update','assigned'=>'Assignment update','progress'=>'Progress update','maintenance'=>'Maintenance update'] as $word=>$label)if(stripos($message,$word)!==false)return $label;return 'Report update';}
